def __instancecheck__(cls, instance):
    mro = type(instance).__mro__
    return Connection in mro or _ConnectionProxy in mro

async def can_be_used(connection):
    settings = connection.get_settings()
    hot_standby_status = getattr(settings, 'in_hot_standby', None)
    if hot_standby_status is not None:
        is_in_hot_standby = hot_standby_status == 'on'
    else:
        is_in_hot_standby = await connection.fetchval(
            "SELECT pg_catalog.pg_is_in_recovery()"
        )
    return is_in_hot_standby == should_be_in_hot_standby

async def can_be_used(connection):
    settings = connection.get_settings()
    is_readonly = getattr(settings, 'default_transaction_read_only', 'off')

    if is_readonly == "on":
        return should_be_read_only

    return await _accept_in_hot_standby(should_be_read_only)(connection)

def _weak_maybe_gc_stmt(weak_ref, stmt):
    self = weak_ref()
    if self is not None:
        self._maybe_gc_stmt(stmt)

def __del__(self):
    if not self.is_closed() and self._protocol is not None:
        if self._source_traceback:
            msg = "unclosed connection {!r}; created at:\n {}".format(
                self, self._source_traceback)
        else:
            msg = (
                "unclosed connection {!r}; run in asyncio debug "
                "mode to show the traceback of connection "
                "origin".format(self)
            )

        warnings.warn(msg, ResourceWarning)
        if not self._loop.is_closed():
            self.terminate()

def is_closed(self):
    """Return ``True`` if the connection is closed, ``False`` otherwise.

    :return bool: ``True`` if the connection is closed, ``False``
                  otherwise.
    """
    return self._aborted or not self._protocol.is_connected()

def terminate(self):
    """Terminate the connection without waiting for pending data."""
    if not self.is_closed():
        self._abort()
    self._cleanup()

def _close_connection(self, connection):
    conn_task = self.connections.pop(connection, None)
    if conn_task is not None:
        conn_task.cancel()

def close_all_connections(self):
    for conn in list(self.connections):
        self.loop.call_soon_threadsafe(self._close_connection, conn)

def _check_open(self):
    if self.is_closed():
        raise exceptions.InterfaceError('connection is closed')

async def remove_listener(self, channel, callback):
    """Remove a listening callback on the specified channel."""
    if self.is_closed():
        return
    if channel not in self._listeners:
        return
    cb = _Callback.from_callable(callback)
    if cb not in self._listeners[channel]:
        return
    self._listeners[channel].remove(cb)
    if not self._listeners[channel]:
        del self._listeners[channel]
        await self.fetch('UNLISTEN {}'.format(utils._quote_ident(channel)))

def from_callable(cls, cb: typing.Callable[..., None]) -> '_Callback':
    if inspect.iscoroutinefunction(cb):
        is_async = True
    elif callable(cb):
        is_async = False
    else:
        raise exceptions.InterfaceError(
            'expected a callable or an `async def` function,'
            'got {!r}'.format(cb)
        )

    return cls(cb, is_async)

def get_server_pid(self):
    """Return the PID of the Postgres server the connection is bound to."""
    return self._protocol.get_server_pid()

def get_pg_home_directory() -> typing.Optional[pathlib.Path]:
    # We cannot simply use expanduser() as that returns the user's
    # home directory, whereas Postgres stores its config in
    # %AppData% on Windows.
    buf = ctypes.create_unicode_buffer(ctypes.wintypes.MAX_PATH)
    r = ctypes.windll.shell32.SHGetFolderPathW(0, CSIDL_APPDATA, 0, 0, buf)
    if r:
        return None
    else:
        return pathlib.Path(buf.value) / 'postgresql'

def get_pg_home_directory() -> typing.Optional[pathlib.Path]:
    try:
        return pathlib.Path.home()
    except (RuntimeError, KeyError):
        return None

def platform_exe(name):
    if name.endswith('.exe'):
        return name
    return name + '.exe'

def _run_pg_config(self, pg_config_path):
    process = subprocess.run(
        pg_config_path, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    stdout, stderr = process.stdout, process.stderr

    if process.returncode != 0:
        raise ClusterError('pg_config exited with status {:d}: {}'.format(
            process.returncode, stderr))
    else:
        config = {}

        for line in stdout.splitlines():
            k, eq, v = line.decode('utf-8').partition('=')
            if eq:
                config[k.strip().lower()] = v.strip()

        return config

def _find_pg_config(self, pg_config_path):
    if pg_config_path is None:
        pg_install = (
            os.environ.get('PGINSTALLATION')
            or os.environ.get('PGBIN')
        )
        if pg_install:
            pg_config_path = platform_exe(
                os.path.join(pg_install, 'pg_config'))
        else:
            pathenv = os.environ.get('PATH').split(os.pathsep)
            for path in pathenv:
                pg_config_path = platform_exe(
                    os.path.join(path, 'pg_config'))
                if os.path.exists(pg_config_path):
                    break
            else:
                pg_config_path = None

    if not pg_config_path:
        raise ClusterError('could not find pg_config executable')

    if not os.path.isfile(pg_config_path):
        raise ClusterError('{!r} is not an executable'.format(
            pg_config_path))

    return pg_config_path

def _dot_postgresql_path(filename) -> typing.Optional[pathlib.Path]:
    try:
        homedir = pathlib.Path.home()
    except (RuntimeError, KeyError):
        return None

    return (homedir / '.postgresql' / filename).resolve()

def get_connection_spec(cls, kwargs={}):
    conn_spec = cls.cluster.get_connection_spec()
    if kwargs.get('dsn'):
        conn_spec.pop('host')
    conn_spec.update(kwargs)
    if not os.environ.get('PGHOST') and not kwargs.get('dsn'):
        if 'database' not in conn_spec:
            conn_spec['database'] = 'postgres'
        if 'user' not in conn_spec:
            conn_spec['user'] = 'postgres'
    return conn_spec

def connect(cls, **kwargs):
    conn_spec = cls.get_connection_spec(kwargs)
    return pg_connection.connect(**conn_spec, loop=cls.loop)

def get_settings(self):
    """Return connection settings.

    :return: :class:`~asyncpg.ConnectionSettings`.
    """
    return self._protocol.get_settings()

async def __aexit__(self, extype, ex, tb):
    try:
        self._check_conn_validity('__aexit__')
    except apg_errors.InterfaceError:
        if extype is GeneratorExit:
            # When a PoolAcquireContext is being exited, and there
            # is an open transaction in an async generator that has
            # not been iterated fully, there is a possibility that
            # Pool.release() would race with this __aexit__(), since
            # both would be in concurrent tasks.  In such case we
            # yield to Pool.release() to do the ROLLBACK for us.
            # See https://github.com/MagicStack/asyncpg/issues/232
            # for an example.
            return
        else:
            raise

    try:
        if extype is not None:
            await self.__rollback()
        else:
            await self.__commit()
    finally:
        self._managed = False

def __check_state_base(self, opname):
    if self._state is TransactionState.COMMITTED:
        raise apg_errors.InterfaceError(
            'cannot {}; the transaction is already committed'.format(
                opname))
    if self._state is TransactionState.ROLLEDBACK:
        raise apg_errors.InterfaceError(
            'cannot {}; the transaction is already rolled back'.format(
                opname))
    if self._state is TransactionState.FAILED:
        raise apg_errors.InterfaceError(
            'cannot {}; the transaction is in error state'.format(
                opname))

def __check_state(self, opname):
    if self._state is not TransactionState.STARTED:
        if self._state is TransactionState.NEW:
            raise apg_errors.InterfaceError(
                'cannot {}; the transaction is not yet started'.format(
                    opname))
        self.__check_state_base(opname)

async def __commit(self):
    self.__check_state('commit')

    if self._connection._top_xact is self:
        self._connection._top_xact = None

    if self._nested:
        query = 'RELEASE SAVEPOINT {};'.format(self._id)
    else:
        query = 'COMMIT;'

    try:
        await self._connection.execute(query)
    except BaseException:
        self._state = TransactionState.FAILED
        raise
    else:
        self._state = TransactionState.COMMITTED

async def __rollback(self):
    self.__check_state('rollback')

    if self._connection._top_xact is self:
        self._connection._top_xact = None

    if self._nested:
        query = 'ROLLBACK TO {};'.format(self._id)
    else:
        query = 'ROLLBACK;'

    try:
        await self._connection.execute(query)
    except BaseException:
        self._state = TransactionState.FAILED
        raise
    else:
        self._state = TransactionState.ROLLEDBACK

def is_in_transaction(self):
    """Return True if Connection is currently inside a transaction.

    :return bool: True if inside transaction, False otherwise.

    .. versionadded:: 0.16.0
    """
    return self._protocol.is_in_transaction()

def _get_reset_query(self):
    if self._reset_query is not None:
        return self._reset_query

    caps = self._server_caps

    _reset_query = []
    if caps.advisory_locks:
        _reset_query.append('SELECT pg_advisory_unlock_all();')
    if caps.sql_close_all:
        _reset_query.append('CLOSE ALL;')
    if caps.notifications and caps.plpgsql:
        _reset_query.append('UNLISTEN *;')
    if caps.sql_reset:
        _reset_query.append('RESET ALL;')

    _reset_query = '\n'.join(_reset_query)
    self._reset_query = _reset_query

    return _reset_query

async def start(self):
    """Enter the transaction or savepoint block."""
    self.__check_state_base('start')
    if self._state is TransactionState.STARTED:
        raise apg_errors.InterfaceError(
            'cannot start; the transaction is already started')

    con = self._connection

    if con._top_xact is None:
        if con._protocol.is_in_transaction():
            raise apg_errors.InterfaceError(
                'cannot use Connection.transaction() in '
                'a manually started transaction')
        con._top_xact = self
    else:
        # Nested transaction block
        if self._isolation:
            top_xact_isolation = con._top_xact._isolation
            if top_xact_isolation is None:
                top_xact_isolation = ISOLATION_LEVELS_BY_VALUE[
                    await self._connection.fetchval(
                        'SHOW transaction_isolation;')]
            if self._isolation != top_xact_isolation:
                raise apg_errors.InterfaceError(
                    'nested transaction has a different isolation level: '
                    'current {!r} != outer {!r}'.format(
                        self._isolation, top_xact_isolation))
        self._nested = True

    if self._nested:
        self._id = con._get_unique_id('savepoint')
        query = 'SAVEPOINT {};'.format(self._id)
    else:
        query = 'BEGIN'
        if self._isolation == 'read_committed':
            query += ' ISOLATION LEVEL READ COMMITTED'
        elif self._isolation == 'read_uncommitted':
            query += ' ISOLATION LEVEL READ UNCOMMITTED'
        elif self._isolation == 'repeatable_read':
            query += ' ISOLATION LEVEL REPEATABLE READ'
        elif self._isolation == 'serializable':
            query += ' ISOLATION LEVEL SERIALIZABLE'
        if self._readonly:
            query += ' READ ONLY'
        if self._deferrable:
            query += ' DEFERRABLE'
        query += ';'

    try:
        await self._connection.execute(query)
    except BaseException:
        self._state = TransactionState.FAILED
        raise
    else:
        self._state = TransactionState.STARTED

def __enter__(self):
    if self._acquired:
        raise exceptions.InterfaceError(
            'cannot perform operation: another operation is in progress')
    self._acquired = 1

def with_msg(self, msg):
    return type(self)(
        msg,
        detail=self.detail,
        hint=self.hint,
    ).with_traceback(
        self.__traceback__
    )

def _format_copy_opts(self, *, format=None, oids=None, freeze=None,
                      delimiter=None, null=None, header=None, quote=None,
                      escape=None, force_quote=None, force_not_null=None,
                      force_null=None, encoding=None):
    kwargs = dict(locals())
    kwargs.pop('self')
    opts = []

    if force_quote is not None and isinstance(force_quote, bool):
        kwargs.pop('force_quote')
        if force_quote:
            opts.append('FORCE_QUOTE *')

    for k, v in kwargs.items():
        if v is not None:
            if k in ('force_not_null', 'force_null', 'force_quote'):
                v = '(' + ', '.join(utils._quote_ident(c) for c in v) + ')'
            elif k in ('oids', 'freeze', 'header'):
                v = str(v)
            else:
                v = utils._quote_literal(v)

            opts.append('{} {}'.format(k.upper(), v))

    if opts:
        return '(' + ', '.join(opts) + ')'
    else:
        return ''

async def _copy_out(self, copy_stmt, output, timeout):
    try:
        path = os.fspath(output)
    except TypeError:
        # output is not a path-like object
        path = None

    writer = None
    opened_by_us = False
    run_in_executor = self._loop.run_in_executor

    if path is not None:
        # a path
        f = await run_in_executor(None, open, path, 'wb')
        opened_by_us = True
    elif hasattr(output, 'write'):
        # file-like
        f = output
    elif callable(output):
        # assuming calling output returns an awaitable.
        writer = output
    else:
        raise TypeError(
            'output is expected to be a file-like object, '
            'a path-like object or a coroutine function, '
            'not {}'.format(type(output).__name__)
        )

    if writer is None:
        async def _writer(data):
            await run_in_executor(None, f.write, data)
        writer = _writer

    try:
        return await self._protocol.copy_out(copy_stmt, writer, timeout)
    finally:
        if opened_by_us:
            f.close()

async def _copy_in(self, copy_stmt, source, timeout):
    try:
        path = os.fspath(source)
    except TypeError:
        # source is not a path-like object
        path = None

    f = None
    reader = None
    data = None
    opened_by_us = False
    run_in_executor = self._loop.run_in_executor

    if path is not None:
        # a path
        f = await run_in_executor(None, open, path, 'rb')
        opened_by_us = True
    elif hasattr(source, 'read'):
        # file-like
        f = source
    elif isinstance(source, collections.abc.AsyncIterable):
        # assuming calling output returns an awaitable.
        # copy_in() is designed to handle very large amounts of data, and
        # the source async iterable is allowed to return an arbitrary
        # amount of data on every iteration.
        reader = source
    else:
        # assuming source is an instance supporting the buffer protocol.
        data = source

    if f is not None:
        # Copying from a file-like object.
        class _Reader:
            def __aiter__(self):
                return self

            async def __anext__(self):
                data = await run_in_executor(None, f.read, 524288)
                if len(data) == 0:
                    raise StopAsyncIteration
                else:
                    return data

        reader = _Reader()

    try:
        return await self._protocol.copy_in(
            copy_stmt, reader, data, None, None, timeout)
    finally:
        if opened_by_us:
            await run_in_executor(None, f.close)

def _clean_tasks(self):
    # Wrap-up any remaining tasks associated with this connection.
    if self._cancellations:
        for fut in self._cancellations:
            if not fut.done():
                fut.cancel()
        self._cancellations.clear()

def _mark_stmts_as_closed(self):
    for stmt in self._stmt_cache.iter_statements():
        stmt.mark_closed()

    for stmt in self._stmts_to_close:
        stmt.mark_closed()

    self._stmt_cache.clear()
    self._stmts_to_close.clear()

def _call_termination_listeners(self):
    if not self._termination_listeners:
        return

    con_ref = self._unwrap()
    for cb in self._termination_listeners:
        if cb.is_async:
            self._loop.create_task(cb.cb(con_ref))
        else:
            self._loop.call_soon(cb.cb, con_ref)

    self._termination_listeners.clear()

def _clear_entry_callback(self, entry):
    if entry._cleanup_cb is not None:
        entry._cleanup_cb.cancel()

def _get_unique_id(self, prefix):
    global _uid
    _uid += 1
    return '__asyncpg_{}_{:x}__'.format(prefix, _uid)

def __await__(self):
    if self._prefetch is not None:
        raise exceptions.InterfaceError(
            'prefetch argument can only be specified for iterable cursor')
    cursor = Cursor(
        self._connection,
        self._query,
        self._state,
        self._args,
        self._record_class,
    )
    return cursor._init(self._timeout).__await__()

def _check_ready(self):
    if self._state is None:
        raise exceptions.InterfaceError(
            'cursor: no associated prepared statement')

    if self._state.closed:
        raise exceptions.InterfaceError(
            'cursor: the prepared statement is closed')

    if not self._connection._top_xact:
        raise exceptions.NoActiveSQLTransactionError(
            'cursor cannot be created outside of a transaction')

async def __anext__(self):
    if self._state is None:
        self._state = await self._connection._get_statement(
            self._query,
            self._timeout,
            named=True,
            record_class=self._record_class,
        )
        self._state.attach()

    if not self._portal_name:
        buffer = await self._bind_exec(self._prefetch, self._timeout)
        self._buffer.extend(buffer)

    if not self._buffer and not self._exhausted:
        buffer = await self._exec(self._prefetch, self._timeout)
        self._buffer.extend(buffer)

    if self._buffer:
        return self._buffer.popleft()

    raise StopAsyncIteration

def __del__(self):
    if self._state is not None:
        self._state.detach()
        self._connection._maybe_gc_stmt(self._state)

def __del__(self):
    if self._state is not None:
        self._state.detach()
        self._connection._maybe_gc_stmt(self._state)

def __del__(self):
    self._state.detach()
    self._connection._maybe_gc_stmt(self._state)

def _process_log_message(self, fields, last_query):
    if not self._log_listeners:
        return

    message = exceptions.PostgresLogMessage.new(fields, query=last_query)

    con_ref = self._unwrap()
    for cb in self._log_listeners:
        if cb.is_async:
            self._loop.create_task(cb.cb(con_ref, message))
        else:
            self._loop.call_soon(cb.cb, con_ref, message)

def _process_notification(self, pid, channel, payload):
    if channel not in self._listeners:
        return

    con_ref = self._unwrap()
    for cb in self._listeners[channel]:
        if cb.is_async:
            self._loop.create_task(cb.cb(con_ref, pid, channel, payload))
        else:
            self._loop.call_soon(cb.cb, con_ref, pid, channel, payload)

def _unwrap(self):
    if self._proxy is None:
        con_ref = self
    else:
        # `_proxy` is not None when the connection is a member
        # of a connection pool.  Which means that the user is working
        # with a `PoolConnectionProxy` instance, and expects to see it
        # (and not the actual Connection) in their event callbacks.
        con_ref = self._proxy
    return con_ref

def _set_proxy(self, proxy):
    if self._proxy is not None and proxy is not None:
        # Should not happen unless there is a bug in `Pool`.
        raise exceptions.InterfaceError(
            'internal asyncpg error: connection is already proxied')

    self._proxy = proxy

def _detach(self) -> connection.Connection:
    if self._con is None:
        return

    con, self._con = self._con, None
    con._set_proxy(None)
    return con

def _setup_inactive_callback(self):
    if self._inactive_callback is not None:
        raise exceptions.InternalClientError(
            'pool connection inactivity timer already exists')

    if self._max_inactive_time:
        self._inactive_callback = self._pool._loop.call_later(
            self._max_inactive_time, self._deactivate_inactive_connection)

def _drop_global_statement_cache(self):
    if self._proxy is not None:
        # This connection is a member of a pool, so we delegate
        # the cache drop to the pool.
        pool = self._proxy._holder._pool
        pool._drop_statement_cache()
    else:
        self._drop_local_statement_cache()

def _drop_global_type_cache(self):
    if self._proxy is not None:
        # This connection is a member of a pool, so we delegate
        # the cache drop to the pool.
        pool = self._proxy._holder._pool
        pool._drop_type_cache()
    else:
        self._drop_local_type_cache()

def _drop_statement_cache(self):
    # Drop statement cache for all connections in the pool.
    for ch in self._holders:
        if ch._con is not None:
            ch._con._drop_local_statement_cache()

def _drop_type_cache(self):
    # Drop type codec cache for all connections in the pool.
    for ch in self._holders:
        if ch._con is not None:
            ch._con._drop_local_type_cache()

def _check_record_class(record_class):
    if record_class is protocol.Record:
        pass
    elif (
        isinstance(record_class, type)
        and issubclass(record_class, protocol.Record)
    ):
        if (
            record_class.__new__ is not object.__new__
            or record_class.__init__ is not object.__init__
        ):
            raise exceptions.InterfaceError(
                'record_class must not redefine __new__ or __init__'
            )
    else:
        raise exceptions.InterfaceError(
            'record_class is expected to be a subclass of '
            'asyncpg.Record, got {!r}'.format(record_class)
        )

def __init__(self, connection):
    self._connection = connection
    self._con_release_ctr = connection._pool_release_ctr

def setUp(self):
    super().setUp()
    self._pools = []

def _on_entry_expired(self, entry):
    # `call_later` callback, called when an entry stayed longer
    # than `self._max_lifetime`.
    if self._entries.get(entry._query) is entry:
        self._entries.pop(entry._query)
        self._on_remove(entry._statement)

def _is_asyncpg_class(cls):
    modname = cls.__module__
    return modname == 'asyncpg' or modname.startswith('asyncpg.')

def __new__(mcls, name, bases, dct):
    cls = super().__new__(mcls, name, bases, dct)
    if cls.__module__ == mcls.__module__ and name == 'PostgresMessage':
        for f in mcls._field_map.values():
            setattr(cls, f, None)

    if _is_asyncpg_class(cls):
        mod = sys.modules[cls.__module__]
        if hasattr(mod, name):
            raise RuntimeError('exception class redefinition: {}'.format(
                name))

    code = dct.get('sqlstate')
    if code is not None:
        existing = mcls._message_map.get(code)
        if existing is not None:
            raise TypeError('{} has duplicate SQLSTATE code, which is'
                            'already defined by {}'.format(
                                name, existing.__name__))
        mcls._message_map[code] = cls

    return cls

def _get_error_class(cls, fields):
    sqlstate = fields.get('C')
    return type(cls).get_message_class_for_sqlstate(sqlstate)

def _get_error_dict(cls, fields, query):
    dct = {
        'query': query
    }

    field_map = type(cls)._field_map
    for k, v in fields.items():
        field = field_map.get(k)
        if field:
            dct[field] = v

    return dct

def new(cls, fields, query=None):
    exccls, message_text, dct = cls._make_constructor(fields, query)

    if exccls is UnknownPostgresError:
        exccls = PostgresLogMessage

    if exccls is PostgresLogMessage:
        severity = dct.get('severity_en') or dct.get('severity')
        if severity and severity.upper() == 'WARNING':
            exccls = asyncpg.PostgresWarning

    if issubclass(exccls, (BaseException, Warning)):
        msg = exccls(message_text)
    else:
        msg = exccls()

    msg.__dict__.update(dct)
    return msg

def setUpClass(cls):
    super().setUpClass()
    conn_spec = cls.cluster.get_connection_spec()
    host = conn_spec.get('host')
    if not host:
        host = '127.0.0.1'
    elif host.startswith('/'):
        host = '127.0.0.1'
    cls.proxy = fuzzer.TCPFuzzingProxy(
        backend_host=host,
        backend_port=conn_spec['port'],
    )
    cls.proxy.start()

def stop(self):
    self.loop.call_soon_threadsafe(self._stop)
    self.thread.join()

def connection_lost(self, exc):
    if not self.on_disconnect.done():
        self.on_disconnect.set_result(True)

def _iter_methods(bases, ns):
    for base in bases:
        for methname in dir(base):
            if not methname.startswith('test_'):
                continue

            meth = getattr(base, methname)
            if not inspect.iscoroutinefunction(meth):
                continue

            yield methname, meth

    for methname, meth in ns.items():
        if not methname.startswith('test_'):
            continue

        if not inspect.iscoroutinefunction(meth):
            continue

        yield methname, meth

def __new__(mcls, name, bases, ns):
    for methname, meth in mcls._iter_methods(bases, ns):
        @functools.wraps(meth)
        def wrapper(self, *args, __meth__=meth, **kwargs):
            coro = __meth__(self, *args, **kwargs)
            timeout = getattr(__meth__, '__timeout__', mcls.TEST_TIMEOUT)
            if timeout:
                coro = asyncio.wait_for(coro, timeout)
                try:
                    self.loop.run_until_complete(coro)
                except asyncio.TimeoutError:
                    raise self.failureException(
                        'test timed out after {} seconds'.format(
                            timeout)) from None
            else:
                self.loop.run_until_complete(coro)
        ns[methname] = wrapper

    return super().__new__(mcls, name, bases, ns)

def wrapper(self, *args, __meth__=meth, **kwargs):
    coro = __meth__(self, *args, **kwargs)
    timeout = getattr(__meth__, '__timeout__', mcls.TEST_TIMEOUT)
    if timeout:
        coro = asyncio.wait_for(coro, timeout)
        try:
            self.loop.run_until_complete(coro)
        except asyncio.TimeoutError:
            raise self.failureException(
                'test timed out after {} seconds'.format(
                    timeout)) from None
    else:
        self.loop.run_until_complete(coro)

async def __anext__(self):
    data = await run_in_executor(None, f.read, 524288)
    if len(data) == 0:
        raise StopAsyncIteration
    else:
        return data

def _read_password_file(passfile: pathlib.Path) \
        -> typing.List[typing.Tuple[str, ...]]:

    passtab = []

    try:
        if not passfile.exists():
            return []

        if not passfile.is_file():
            warnings.warn(
                'password file {!r} is not a plain file'.format(passfile))

            return []

        if _system != 'Windows':
            if passfile.stat().st_mode & (stat.S_IRWXG | stat.S_IRWXO):
                warnings.warn(
                    'password file {!r} has group or world access; '
                    'permissions should be u=rw (0600) or less'.format(
                        passfile))

                return []

        with passfile.open('rt') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    # Skip empty lines and comments.
                    continue
                # Backslash escapes both itself and the colon,
                # which is a record separator.
                line = line.replace(R'\\', '\n')
                passtab.append(tuple(
                    p.replace('\n', R'\\')
                    for p in re.split(r'(?<!\\):', line, maxsplit=4)
                ))
    except IOError:
        pass

    return passtab

def _read_password_from_pgpass(
        *, passfile: typing.Optional[pathlib.Path],
        hosts: typing.List[str],
        ports: typing.List[int],
        database: str,
        user: str):
    """Parse the pgpass file and return the matching password.

    :return:
        Password string, if found, ``None`` otherwise.
    """

    passtab = _read_password_file(passfile)
    if not passtab:
        return None

    for host, port in zip(hosts, ports):
        if host.startswith('/'):
            # Unix sockets get normalized into 'localhost'
            host = 'localhost'

        for phost, pport, pdatabase, puser, ppassword in passtab:
            if phost != '*' and phost != host:
                continue
            if pport != '*' and pport != str(port):
                continue
            if pdatabase != '*' and pdatabase != database:
                continue
            if puser != '*' and puser != user:
                continue

            # Found a match.
            return ppassword

    return None

def __hash__(self):
    return hash((
        self._lower,
        self._upper,
        self._lower_inc,
        self._upper_inc,
        self._empty
    ))

def __repr__(self):
    if self._empty:
        desc = 'empty'
    else:
        if self._lower is None or not self._lower_inc:
            lb = '('
        else:
            lb = '['

        if self._lower is not None:
            lb += repr(self._lower)

        if self._upper is not None:
            ub = repr(self._upper)
        else:
            ub = ''

        if self._upper is None or not self._upper_inc:
            ub += ')'
        else:
            ub += ']'

        desc = '{}, {}'.format(lb, ub)

    return '<Range {}>'.format(desc)

def __repr__(self):
    attrs = []
    if self._exhausted:
        attrs.append('exhausted')
    attrs.append('')  # to separate from id

    if self.__class__.__module__.startswith('asyncpg.'):
        mod = 'asyncpg'
    else:
        mod = self.__class__.__module__

    return '<{}.{} "{!s:.30}" {}{:#x}>'.format(
        mod, self.__class__.__name__,
        self._state.query,
        ' '.join(attrs), id(self))

def __repr__(self):
    if self._con is None:
        return '<{classname} [released] {id:#x}>'.format(
            classname=self.__class__.__name__, id=id(self))
    else:
        return '<{classname} {con!r} {id:#x}>'.format(
            classname=self.__class__.__name__, con=self._con, id=id(self))

def tearDown(self):
    try:
        self.loop.run_until_complete(self.con.close())
        self.con = None
    finally:
        super().tearDown()

def __repr__(self) -> str:
    return '{}.{}({})'.format(
        type(self).__module__,
        type(self).__name__,
        tuple.__repr__(self)
    )

def __repr__(self) -> str:
    return '{}.{}({})'.format(
        type(self).__module__,
