def as_string(self) -> str:
    s = ''

    for i in range(self._bitlength):
        s += str(self._getitem(i))
        if i % 4 == 3:
            s += ' '

    return s.strip()

def __init__(self, *, detail=None, hint=None):
    self.detail = detail
